<?php
namespace Database\Factories; use App\Models\Client; use Illuminate\Database\Eloquent\Factories\Factory; use Illuminate\Support\Str; class ClientFactory extends Factory { protected $model=Client::class; public function definition():array{$name=fake()->unique()->company();return ['name'=>$name,'slug'=>Str::slug($name).'-'.fake()->unique()->numberBetween(1,99999),'client_type'=>'client','short_description'=>fake()->sentence(),'status'=>'draft','is_featured'=>false,'display_order'=>1,'robots_index'=>true,'robots_follow'=>true];} public function published():static{return $this->state(fn()=>['status'=>'published','published_at'=>now(),'archived_at'=>null]);} }
